func (u *AccessKeyUpsertBulk) Update(set func(*AccessKeyUpsert)) *AccessKeyUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&AccessKeyUpsert{UpdateSet: update})
	}))
	return u
}

